<script setup>
import {ref} from 'vue'
import {api} from '../lib/api'
const props=defineProps({modelValue:{type:Array,default:()=>[]},imagesOnly:Boolean,disabled:Boolean}),emit=defineEmits(['update:modelValue','busy']),busy=ref(false),error=ref('')
async function choose(event){const chosen=[...event.target.files];if(props.modelValue.length+chosen.length>3){error.value='최대 3개까지 첨부할 수 있어요.';event.target.value='';return}busy.value=true;emit('busy',true);error.value='';try{const result=[...props.modelValue];for(const file of chosen){if(file.size>1048576)throw Error('파일당 최대 1MB입니다.');if(props.imagesOnly&&!/^image\/(png|jpeg|gif|webp)$/.test(file.type))throw Error('PNG·JPG·GIF·WEBP 이미지를 선택하세요.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('파일을 읽을 수 없어요.'));reader.readAsDataURL(file)});const uploaded=await api('/files',{method:'POST',body:{name:file.name,data}});result.push(uploaded);emit('update:modelValue',[...result])}}catch(e){error.value=e.message}finally{busy.value=false;emit('busy',false);event.target.value=''}}
</script>
<template><div class="file-picker"><label>📎 {{imagesOnly?'이미지':'파일·이미지'}} 첨부 <small>최대 3개 · 파일당 1MB</small><input type="file" multiple :accept="imagesOnly?'image/png,image/jpeg,image/gif,image/webp':'.png,.jpg,.jpeg,.gif,.webp,.pdf,.txt,.md,.csv,.json,.py,.js,.java,.sql,.vue'" :disabled="disabled||busy||modelValue.length>=3" @change="choose"/></label><p v-if="busy" role="status">첨부를 업로드하고 있어요…</p><ul><li v-for="file in modelValue" :key="file.id">{{file.name}} <button type="button" class="text-button" :disabled="disabled||busy" :aria-label="file.name+' 첨부 취소'" @click="emit('update:modelValue',modelValue.filter(f=>f.id!==file.id))">✕</button></li></ul><p v-if="error" role="alert">{{error}}</p></div></template>
<style scoped>.file-picker{padding:10px 0;min-width:0}.file-picker label{display:flex;flex-direction:column;gap:7px;font-size:12px}.file-picker small,.file-picker p,.file-picker li{font-size:11px;overflow-wrap:anywhere}.file-picker input{max-width:100%;min-width:0;box-sizing:border-box}.file-picker button{padding:3px 8px}.file-picker ul{padding-left:20px}</style>
